/* ===================== BÀI 58 · Tích hợp prototype ===================== */
/* Bài 58 · Tích hợp prototype (AMTS-EMB-001-M15-L02, MC51-058) — sinh bởi tools/author/mcu8051/l58.py, không sửa tay.
   Ví dụ cho trình mô phỏng 8051 và bài tập chấm tự động (đề, code mẫu, bộ thử). Lời giải không nằm ở đây. */
const P58=[{"label":"Ví dụ: Khung khởi tạo và tick 1 ms (thăm dò TF0)","code":"; Bước 1 của tích hợp: khung khởi tạo + tick 1 ms (thăm dò)\nTICK    DATA    30H                     ; số tick đã qua\n        ORG     0000H\n        MOV     SP,#5FH                 ; ngăn xếp 60H–7FH (Bài 57)\n        MOV     TMOD,#01H               ; Timer 0 chế độ 1\n        MOV     TICK,#0\nNAP:    MOV     TH0,#0FCH               ; 65536 − 1000 = FC18H\n        MOV     TL0,#18H\n        SETB    TR0\nCHO:    JNB     TF0,CHO                 ; chờ tràn\n        CLR     TR0\n        CLR     TF0\n        INC     TICK\n        MOV     A,TICK\n        CJNE    A,#3,NAP                ; 3 tick rồi dừng\n        SJMP    $\n        END\n","note":"Khung đầu tiên của tích hợp: SP = 5FH, Timer 0 chế độ 1, chờ TF0 ba lần. Đoán trước: tổng số chu kỳ tới SJMP $? (6 khởi tạo + 3 × (1 000 đếm + 11 lệnh) = 3 039 chu kỳ = 3 039 µs.) JNB TF0,CHO chạy 500 lần mỗi tick (2 chu kỳ mỗi lần).","dev":{"led":true},"fosc":12000000},{"label":"Ví dụ: Bộ lập lịch chia tần theo tick","code":"; Bộ lập lịch theo tick: A mỗi tick, B mỗi 4 tick,\n; C mỗi 10 tick. Chạy 20 tick (tick giả lập bằng vòng lặp).\n        ORG     0000H\n        MOV     R7,#20                  ; số tick\n        MOV     R2,#4                   ; đếm lùi của B\n        MOV     R3,#10                  ; đếm lùi của C\n        CLR     A\n        MOV     30H,A                   ; số lần chạy A\n        MOV     31H,A                   ; số lần chạy B\n        MOV     32H,A                   ; số lần chạy C\nTICK:   INC     30H                     ; tác vụ A\n        DJNZ    R2,XC\n        MOV     R2,#4\n        INC     31H                     ; tác vụ B\nXC:     DJNZ    R3,TIEP\n        MOV     R3,#10\n        INC     32H                     ; tác vụ C\nTIEP:   DJNZ    R7,TICK\n        SJMP    $\n        END\n","note":"Ba bộ đếm lùi R2 (chu kỳ 4), R3 (chu kỳ 10) cho tác vụ B, C; tác vụ A chạy mỗi tick. Đoán trước: sau 20 tick, 30H, 31H, 32H bằng bao nhiêu? (14H = 20, 05H, 02H.) Mỗi tick tốn 7 chu kỳ cơ bản, thêm 2 khi B hoặc C chạy: 7 + 20 × 7 + 5 × 2 + 2 × 2 = 161 chu kỳ.","dev":{"led":true},"fosc":12000000},{"label":"Ví dụ: Bộ đệm vòng cho UART","code":"; Bộ đệm vòng 8 byte (40H–47H) giữa vòng chính và UART.\n; DAU = chỉ số ghi, CUOI = chỉ số đọc, quay vòng bằng AND 07H.\nDAU     DATA    30H\nCUOI    DATA    31H\n        ORG     0000H\n        MOV     SP,#5FH\n        MOV     DAU,#6                  ; giả định: bộ đệm đã chạy một lúc\n        MOV     CUOI,#6\n        MOV     DPTR,#CHUOI\n        MOV     R7,#5                   ; ghi 5 byte: C = 4 2 CR\nGHI:    CLR     A\n        MOVC    A,@A+DPTR\n        INC     DPTR\n        ACALL   DAT\n        DJNZ    R7,GHI\n        MOV     R1,#50H                 ; lấy 3 byte ra 50H (thay cho SBUF)\n        MOV     R7,#3\nLAY:    ACALL   LAYRA\n        MOV     @R1,A\n        INC     R1\n        DJNZ    R7,LAY\n        SJMP    $\nDAT:    MOV     R6,A                    ; vào: A = byte cần ghi\n        MOV     A,DAU\n        ADD     A,#40H\n        MOV     R0,A\n        MOV     A,R6\n        MOV     @R0,A\n        INC     DAU\n        ANL     DAU,#07H                ; 8 → 0\n        RET\nLAYRA:  MOV     A,CUOI                  ; ra: A = byte cũ nhất\n        ADD     A,#40H\n        MOV     R0,A\n        MOV     A,@R0\n        INC     CUOI\n        ANL     CUOI,#07H\n        RET\nCHUOI:  DB      'C','=','4','2',0DH\n        END\n","note":"DAU = CUOI = 6. Ghi 5 byte “C=42” CR vào 46H, 47H, 40H, 41H, 42H (quay vòng sau 47H), DAU = 3. Lấy 3 byte cũ nhất ra 50H–52H: 43H, 3DH, 34H; CUOI = 1. Đoán trước: còn bao nhiêu byte trong bộ đệm? (DAU − CUOI = 2: “2” và CR.)","dev":{"led":true},"fosc":12000000},{"label":"Bẫy: Quên CLR TF0 — 3 “tick” trong 1,04 ms","code":"; Bẫy khi ghép: chép khung ví dụ 1 nhưng quên CLR TF0\nTICK    DATA    30H\n        ORG     0000H\n        MOV     SP,#5FH\n        MOV     TMOD,#01H\n        MOV     TICK,#0\nNAP:    MOV     TH0,#0FCH\n        MOV     TL0,#18H\n        SETB    TR0\nCHO:    JNB     TF0,CHO                 ; TF0 vẫn = 1 từ tick trước!\n        CLR     TR0\n        INC     TICK\n        MOV     A,TICK\n        CJNE    A,#3,NAP\n        SJMP    $\n        END\n","note":"Giống ví dụ 1 nhưng thiếu CLR TF0. Tick 1 đúng 1 010 chu kỳ; tick 2 và 3 mỗi tick chỉ 12 chu kỳ vì JNB TF0 thấy TF0 = 1 ngay. Đoán trước: “3 tick” mất bao lâu? (1 040 µs thay vì khoảng 3 ms.) Cuối chương trình TF0 vẫn = 1.","dev":{"led":true},"fosc":12000000},{"label":"Bẫy: Mô-đun phá thanh ghi của người gọi","code":"; Bẫy khi ghép: mô-đun DAT (bộ đệm vòng) dùng R0 mà không\n; ghi trong giao diện; người gọi cũng dùng R0 làm con trỏ.\nDAU     DATA    30H\n        ORG     0000H\n        MOV     SP,#5FH\n        MOV     DAU,#0\n        MOV     50H,#'O'                ; cần chép \"OK\" CR vào bộ đệm\n        MOV     51H,#'K'\n        MOV     52H,#0DH\n        MOV     R0,#50H                 ; con trỏ nguồn\n        MOV     R7,#3\nCHEP:   MOV     A,@R0\n        ACALL   DAT                     ; DAT đổi R0!\n        INC     R0\n        DJNZ    R7,CHEP\n        SJMP    $\nDAT:    MOV     R6,A\n        MOV     A,DAU\n        ADD     A,#40H\n        MOV     R0,A                    ; phá con trỏ của người gọi\n        MOV     A,R6\n        MOV     @R0,A\n        INC     DAU\n        ANL     DAU,#07H\n        RET\n        END\n","note":"Lần 1: A = 'O' (4FH), DAT đặt R0 = 40H. Người gọi INC R0 → 41H rồi đọc @41H = 00H thay vì 'K'. Đoán trước: 40H, 41H, 42H bằng gì? (4FH, 00H, 00H.) Sửa: DAT PUSH/POP R0 (qua ô 00H của băng 0, ví dụ PUSH 00H), hoặc người gọi dùng R1 và giao diện ghi rõ “DAT phá R0, R6”.","dev":{"led":true},"fosc":12000000}];
const sim58=makeSim51(document.getElementById("m51-l58"),{id:"s58",presets:P58,ram:256});
makeEx51(document.getElementById("ex-l58"),"l58",[{"t":"Bộ chia tần của bộ lập lịch","d":"<p>Bộ lập lịch có 3 tác vụ. Ô <code>30H<\/code> = số tick N (0–255); ô <code>31H<\/code>, <code>32H<\/code>, <code>33H<\/code> = chu kỳ (tính bằng tick, 1–255) của tác vụ 0, 1, 2. Mỗi tác vụ có một bộ đếm lùi bắt đầu bằng chu kỳ của nó; mỗi tick bộ đếm giảm 1, về 0 thì tác vụ chạy một lần và bộ đếm nạp lại chu kỳ. Ghi số lần chạy của tác vụ 0, 1, 2 trong N tick vào <code>34H<\/code>, <code>35H<\/code>, <code>36H<\/code>. Kết thúc bằng <code>SJMP $<\/code>.<\/p><p>Ví dụ: N = 20, chu kỳ 1, 4, 10 → <code>34H = 14H<\/code> (20), <code>35H = 05H<\/code>, <code>36H = 02H<\/code> (giống ví dụ 2).<\/p>","start":"        ORG     0000H\n        MOV     R7,30H                  ; số tick N\n        MOV     R2,31H                  ; đếm lùi của tác vụ 0\n        MOV     34H,#0\nTICK:   DJNZ    R2,TIEP\n        MOV     R2,31H                  ; nạp lại chu kỳ\n        INC     34H                     ; tác vụ 0 chạy\nTIEP:                                   ; Viết thêm: tác vụ 1 (32H → 35H), tác\n                                        ; vụ 2 (33H → 36H)\n        DJNZ    R7,TICK\n        SJMP    $\n        END\n","spec":{"cases":[{"setup":{"iram":{"0x30":20,"0x31":1,"0x32":4,"0x33":10,"0x34":238,"0x35":238,"0x36":238}},"expect":{"iram":{"0x34":20,"0x35":5,"0x36":2}}},{"setup":{"iram":{"0x30":0,"0x31":1,"0x32":1,"0x33":1,"0x34":238,"0x35":238,"0x36":238}},"expect":{"iram":{"0x34":0,"0x35":0,"0x36":0}}},{"setup":{"iram":{"0x30":255,"0x31":1,"0x32":255,"0x33":16,"0x34":238,"0x35":238,"0x36":238}},"expect":{"iram":{"0x34":255,"0x35":1,"0x36":15}}},{"setup":{"iram":{"0x30":100,"0x31":3,"0x32":7,"0x33":200,"0x34":238,"0x35":238,"0x36":238}},"expect":{"iram":{"0x34":33,"0x35":14,"0x36":0}}},{"setup":{"iram":{"0x30":12,"0x31":12,"0x32":6,"0x33":5,"0x34":238,"0x35":238,"0x36":238}},"expect":{"iram":{"0x34":1,"0x35":2,"0x36":2}}},{"setup":{"iram":{"0x30":255,"0x31":2,"0x32":128,"0x33":255,"0x34":238,"0x35":238,"0x36":238}},"expect":{"iram":{"0x34":127,"0x35":1,"0x36":1}}}]},"hints":["Code mẫu đã làm tác vụ 0. Thêm hai bộ đếm lùi R3, R4 nạp từ 32H, 33H, và hai đoạn DJNZ giống hệt đoạn của tác vụ 0.","Ô kết quả có giá trị rác lúc đầu: xóa 34H–36H trước vòng lặp.","N = 0 thì DJNZ R7 với R7 = 0 chạy 256 vòng chứ không phải 0. Kiểm N bằng MOV A,30H rồi JZ trước khi vào vòng lặp."],"why":"Tích hợp thêm tác vụ vào bộ lập lịch = thêm một bộ đếm lùi giống hệt, không viết lại khung. Bộ thử 2 (N = 0) bắt lỗi DJNZ với bộ đếm bằng 0 (256 vòng); bộ thử 4 kiểm tác vụ có chu kỳ dài hơn N."},{"t":"Bộ đệm vòng có đếm byte mất","d":"<p>Bộ đệm vòng 8 byte ở <code>40H<\/code>–<code>47H<\/code>. Ô <code>30H<\/code> = DAU (chỉ số ô sẽ ghi, 0–7), <code>31H<\/code> = SO (số byte đang có, 0–8), <code>32H<\/code> = MAT (số byte đã bị mất). Có N byte mới (N ở <code>33H<\/code>, 0–16) nằm từ ô <code>50H<\/code>. Với từng byte theo thứ tự: nếu SO &lt; 8 thì ghi vào ô <code>40H + DAU<\/code>, tăng DAU (7 quay về 0) và tăng SO; nếu SO = 8 (đầy) thì bỏ byte đó và tăng MAT. Các ô khác của bộ đệm giữ nguyên. Kết thúc bằng <code>SJMP $<\/code>.<\/p><p>Ví dụ: DAU = 6, SO = 0, 5 byte <code>43H 3DH 34H 32H 0DH<\/code> → ghi vào 46H, 47H, 40H, 41H, 42H; DAU = 3, SO = 5, MAT = 0.<\/p>","start":"        ORG     0000H\n        MOV     R1,#50H                 ; con trỏ dữ liệu vào\n        MOV     A,33H                   ; số byte N\n        JZ      XONG\n        MOV     R7,A\nLAP:    MOV     A,30H                   ; DAU\n        ADD     A,#40H\n        MOV     R0,A\n        MOV     A,@R1\n        MOV     @R0,A                   ; ghi vào ô DAU\n        INC     30H                     ; Viết thêm: quay vòng 7 → 0\n        INC     31H                     ; Viết thêm: kiểm đầy, đếm MAT\n        INC     R1\n        DJNZ    R7,LAP\nXONG:   SJMP    $\n        END\n","spec":{"cases":[{"setup":{"iram":{"0x30":6,"0x31":0,"0x32":0,"0x33":5,"0x40":238,"0x41":238,"0x42":238,"0x43":238,"0x44":238,"0x45":238,"0x46":238,"0x47":238,"0x50":67,"0x51":61,"0x52":52,"0x53":50,"0x54":13}},"expect":{"iram":{"0x30":3,"0x31":5,"0x32":0,"0x40":52,"0x41":50,"0x42":13,"0x43":238,"0x44":238,"0x45":238,"0x46":67,"0x47":61}}},{"setup":{"iram":{"0x30":3,"0x31":2,"0x32":0,"0x33":0,"0x40":238,"0x41":238,"0x42":238,"0x43":238,"0x44":238,"0x45":238,"0x46":238,"0x47":238}},"expect":{"iram":{"0x30":3,"0x31":2,"0x32":0,"0x40":238,"0x41":238,"0x42":238,"0x43":238,"0x44":238,"0x45":238,"0x46":238,"0x47":238}}},{"setup":{"iram":{"0x30":0,"0x31":0,"0x32":0,"0x33":8,"0x40":238,"0x41":238,"0x42":238,"0x43":238,"0x44":238,"0x45":238,"0x46":238,"0x47":238,"0x50":16,"0x51":17,"0x52":18,"0x53":19,"0x54":20,"0x55":21,"0x56":22,"0x57":23}},"expect":{"iram":{"0x30":0,"0x31":8,"0x32":0,"0x40":16,"0x41":17,"0x42":18,"0x43":19,"0x44":20,"0x45":21,"0x46":22,"0x47":23}}},{"setup":{"iram":{"0x30":2,"0x31":6,"0x32":0,"0x33":5,"0x40":238,"0x41":238,"0x42":238,"0x43":238,"0x44":238,"0x45":238,"0x46":238,"0x47":238,"0x50":161,"0x51":162,"0x52":163,"0x53":164,"0x54":165}},"expect":{"iram":{"0x30":4,"0x31":8,"0x32":3,"0x40":238,"0x41":238,"0x42":161,"0x43":162,"0x44":238,"0x45":238,"0x46":238,"0x47":238}}},{"setup":{"iram":{"0x30":7,"0x31":0,"0x32":0,"0x33":3,"0x40":238,"0x41":238,"0x42":238,"0x43":238,"0x44":238,"0x45":238,"0x46":238,"0x47":238,"0x50":49,"0x51":50,"0x52":51}},"expect":{"iram":{"0x30":2,"0x31":3,"0x32":0,"0x40":50,"0x41":51,"0x42":238,"0x43":238,"0x44":238,"0x45":238,"0x46":238,"0x47":49}}},{"setup":{"iram":{"0x30":5,"0x31":8,"0x32":4,"0x33":2,"0x40":238,"0x41":238,"0x42":238,"0x43":238,"0x44":238,"0x45":238,"0x46":238,"0x47":238,"0x50":85,"0x51":102}},"expect":{"iram":{"0x30":5,"0x31":8,"0x32":6,"0x40":238,"0x41":238,"0x42":238,"0x43":238,"0x44":238,"0x45":238,"0x46":238,"0x47":238}}},{"setup":{"iram":{"0x30":0,"0x31":0,"0x32":0,"0x33":16,"0x40":238,"0x41":238,"0x42":238,"0x43":238,"0x44":238,"0x45":238,"0x46":238,"0x47":238,"0x50":128,"0x51":129,"0x52":130,"0x53":131,"0x54":132,"0x55":133,"0x56":134,"0x57":135,"0x58":136,"0x59":137,"0x5A":138,"0x5B":139,"0x5C":140,"0x5D":141,"0x5E":142,"0x5F":143}},"expect":{"iram":{"0x30":0,"0x31":8,"0x32":8,"0x40":128,"0x41":129,"0x42":130,"0x43":131,"0x44":132,"0x45":133,"0x46":134,"0x47":135}}}]},"hints":["Code mẫu ghi đúng ô nhưng DAU không quay vòng và không kiểm đầy. Quay vòng: sau INC 30H thêm ANL 30H,#07H.","Kiểm đầy trước khi ghi: MOV A,31H rồi CJNE A,#8,… — bằng 8 thì chỉ INC 32H và sang byte kế tiếp, không ghi, không đổi DAU và SO.","Con trỏ nguồn R1 phải tăng với mọi byte, kể cả byte bị bỏ; đặt INC R1 sau chỗ hai nhánh gặp nhau."],"why":"Bộ đệm vòng là chỗ nối hai mô-đun chạy khác nhịp (vòng chính và UART). Khi đầy phải có quy tắc rõ ràng (ở đây: bỏ byte mới và đếm) để nghiệm thu được ở Bài 59. Bộ thử 4, 6, 7 bắt lỗi không kiểm đầy; bộ thử 1, 5 bắt lỗi quên quay vòng; bộ thử 6 kiểm MAT cộng dồn chứ không ghi đè."},{"t":"Một tick của bộ lập lịch ≤ 26 chu kỳ","d":"<p>Bộ lập lịch có 4 tác vụ. Ô <code>40H<\/code>–<code>43H<\/code> = chu kỳ (1–255) của tác vụ 0–3; ô <code>44H<\/code>–<code>47H<\/code> = bộ đếm lùi hiện tại (1 … chu kỳ). Viết đoạn chạy <b>một tick<\/b>: với từng tác vụ <i>i<\/i>, giảm bộ đếm 1; nếu về 0 thì nạp lại chu kỳ và bật bit <i>i<\/i> của mặt nạ “đến hạn”. Ghi mặt nạ (chỉ gồm các tác vụ đến hạn ở tick này) vào <code>30H<\/code>. Giữ nguyên 40H–43H. Kết thúc bằng <code>SJMP $<\/code>.<\/p><p>Đoạn này chạy mỗi tick nên phải rẻ. Code mẫu đúng nhưng chậm. Yêu cầu: không quá <b>26 chu kỳ máy<\/b> với mọi bộ thử (tính cả một lần <code>SJMP $<\/code>) và không quá <b>40 byte<\/b> mã.<\/p>","start":"        ORG     0000H\n        MOV     30H,#0                  ; mặt nạ tác vụ đến hạn\n        MOV     R0,#44H                 ; đếm lùi\n        MOV     R1,#40H                 ; chu kỳ\n        MOV     R2,#01H                 ; bit của tác vụ\nLAP:    DEC     @R0\n        MOV     A,@R0\n        JNZ     TIEP\n        MOV     A,@R1                   ; về 0: nạp lại, bật bit\n        MOV     @R0,A\n        MOV     A,R2\n        ORL     30H,A\nTIEP:   INC     R0\n        INC     R1\n        MOV     A,R2\n        RL      A\n        MOV     R2,A\n        CJNE    R2,#10H,LAP\n        SJMP    $\n        END\n","spec":{"cases":[{"setup":{"iram":{"0x40":1,"0x41":4,"0x42":10,"0x43":100,"0x44":1,"0x45":3,"0x46":1,"0x47":50,"0x30":238}},"expect":{"iram":{"0x30":5,"0x44":1,"0x45":2,"0x46":10,"0x47":49,"0x40":1,"0x41":4,"0x42":10,"0x43":100}}},{"setup":{"iram":{"0x40":2,"0x41":3,"0x42":4,"0x43":5,"0x44":1,"0x45":1,"0x46":1,"0x47":1,"0x30":238}},"expect":{"iram":{"0x30":15,"0x44":2,"0x45":3,"0x46":4,"0x47":5,"0x40":2,"0x41":3,"0x42":4,"0x43":5}}},{"setup":{"iram":{"0x40":9,"0x41":9,"0x42":9,"0x43":9,"0x44":5,"0x45":5,"0x46":5,"0x47":5,"0x30":238}},"expect":{"iram":{"0x30":0,"0x44":4,"0x45":4,"0x46":4,"0x47":4,"0x40":9,"0x41":9,"0x42":9,"0x43":9}}},{"setup":{"iram":{"0x40":255,"0x41":255,"0x42":255,"0x43":255,"0x44":2,"0x45":1,"0x46":2,"0x47":1,"0x30":238}},"expect":{"iram":{"0x30":10,"0x44":1,"0x45":255,"0x46":1,"0x47":255,"0x40":255,"0x41":255,"0x42":255,"0x43":255}}},{"setup":{"iram":{"0x40":1,"0x41":1,"0x42":1,"0x43":1,"0x44":1,"0x45":1,"0x46":1,"0x47":1,"0x30":238}},"expect":{"iram":{"0x30":15,"0x44":1,"0x45":1,"0x46":1,"0x47":1,"0x40":1,"0x41":1,"0x42":1,"0x43":1}}},{"setup":{"iram":{"0x40":3,"0x41":7,"0x42":2,"0x43":9,"0x44":2,"0x45":1,"0x46":1,"0x47":3,"0x30":238}},"expect":{"iram":{"0x30":6,"0x44":1,"0x45":7,"0x46":2,"0x47":2,"0x40":3,"0x41":7,"0x42":2,"0x43":9}}}],"maxCyc":26,"maxBytes":40},"hints":["Chạy code mẫu với bộ thử 2 (cả 4 tác vụ đến hạn): khoảng 60 chu kỳ. Vòng lặp, con trỏ @R0/@R1 và việc xoay mặt nạ trong R2 tốn nhiều hơn chính công việc.","Chỉ có 4 tác vụ: trải vòng lặp ra. DJNZ chạy được thẳng trên ô RAM (DJNZ 44H,nhãn: 3 byte, 2 chu kỳ), và MOV 44H,40H chép ô sang ô trong 2 chu kỳ.","Gom mặt nạ trong A, ghi ra ô một lần ở cuối."],"why":"Vòng lặp tổng quát trả giá cho con trỏ và bộ đếm vòng ở mỗi tick; với số tác vụ cố định, trải vòng lặp và dùng DJNZ trực tiếp trên ô RAM rẻ hơn nhiều. Lời giải 37 byte, 24 chu kỳ khi cả 4 tác vụ đến hạn; cách MOV 30H,#0 + ORL 30H,#bit đúng nhưng 28 chu kỳ nên trượt chỉ tiêu."}]);

makeQuiz("quiz58","score58",[{"q": "Ghép thêm mô-đun quét phím vào khung đã chạy đúng thì số đếm hiển thị sai. Theo cách tích hợp tăng dần, nên nghi phần nào trước?", "o": ["Timer 0, vì tick là phần chạy đầu tiên", "Mô-đun quét phím vừa thêm và chỗ nó dùng chung với phần cũ (chân, thanh ghi, RAM)", "Trình dịch, vì build có thể sai", "Toàn bộ chương trình, phải viết lại từ đầu"], "a": 1, "e": "Các bước trước đã chạy đúng với cùng kịch bản; kết quả đổi ngay sau khi thêm quét phím nên lỗi nằm ở phần mới hoặc ở chỗ nó đụng phần cũ (ví dụ 5: phá R0; Bài 57 ví dụ 6: chung cổng)."}, {"q": "Vòng chờ tick dùng JNB TF0,CHO nhưng không có CLR TF0. Điều gì xảy ra từ tick thứ hai?", "o": ["Vòng chờ thoát ngay vì TF0 vẫn bằng 1, tick chỉ còn khoảng 12 µs", "CPU tự vào chương trình ngắt và xóa TF0", "Timer dừng vì TF0 = 1", "Không sao, TF0 tự xóa khi đọc"], "a": 0, "e": "Phần cứng chỉ xóa TF0 khi vào chương trình ngắt Timer 0. Thăm dò thì phần mềm phải CLR TF0; thiếu nó, mỗi tick sau chỉ 12 chu kỳ (12 µs ở 12 MHz) và ví dụ 4 chạy “3 tick” trong 1 040 µs."}, {"q": "Bộ đệm vòng 8 byte, DAU = 7. Ghi một byte rồi tăng DAU bằng INC rồi ANL DAU,#07H. DAU mới là bao nhiêu?", "o": ["0", "8", "7", "FFH"], "a": 0, "e": "7 + 1 = 8 = 00001000B; AND 07H giữ 3 bit thấp → 0. Kích thước bộ đệm là lũy thừa của 2 nên quay vòng chỉ cần một lệnh AND."}, {"q": "Đoạn mã chạy mỗi tick cần giảm 4 bộ đếm trong RAM. Cách nào ít chu kỳ nhất trên 8051?", "o": ["Vòng lặp với DEC @R0 rồi MOV A,@R0 và JNZ", "Đưa từng ô vào A, SUBB A,#1, ghi lại", "Dùng MUL AB để tính địa chỉ từng ô", "Trải vòng lặp: DJNZ trực tiếp trên từng ô RAM (2 chu kỳ mỗi ô)"], "a": 3, "e": "DJNZ direct,rel vừa giảm vừa kiểm trong 2 chu kỳ, không cần con trỏ hay A; với số tác vụ cố định, trải vòng lặp bỏ được chi phí của bộ đếm vòng (bài tập 3: 24 chu kỳ)."}, {"q": "Chương trình con DAT dùng R0 bên trong. Giao diện của DAT cần ghi gì để người gọi không bị lỗi như ví dụ 5?", "o": ["Chỉ cần tên chương trình con", "Chỉ cần địa chỉ bắt đầu của DAT", "Vào, ra và các thanh ghi bị phá (R0, R6) — hoặc DAT tự cất và khôi phục chúng", "Không cần ghi gì vì RET khôi phục mọi thanh ghi"], "a": 2, "e": "RET chỉ lấy lại PC từ ngăn xếp, không khôi phục thanh ghi. Giao diện mô-đun phải nêu thanh ghi bị phá, hoặc chương trình con PUSH/POP chúng."}]);

